from lib import *
S = SS('t8')
steps = [
    step("正常成功的一单,编排式和协同式的区别一眼可见。编排式:一个编排器按顺序调用——先建订单(PENDING),调库存服务(14.0 ms 成功)、调支付服务(21.1 ms 成功),最后把订单改成 CONFIRMED,全程 21.3 ms,没有消息队列。协同式:订单服务建订单并发出 order.created(0.4 ms),库存服务收到后预留并发出 stock.reserved(8.1 ms),支付服务收到后扣款并发出 payment.succeeded(16.3 ms),订单服务收到后确认(16.7 ms),这一单在 RabbitMQ 上走了 3 条消息。两种写法最终的数据完全一样:订单 CONFIRMED、库存 99、余额 999920。差别在于“谁知道整个流程”:编排器知道,协同式里没有任何一个服务知道。", t=tl(S(1)), mark=lidx(S(1), '协同式这一单在 RabbitMQ 上走了'), done=lidx(S(1), '编排式(一个编排器', '协同式(服务之间'), b=bars([['编排式 总耗时 ms', 21.3, '21.3'], ['协同式 到订单确认 ms', 16.7, '16.7'], ['协同式 RabbitMQ 消息数', 3, '3']], 25, cur=[0, 1], mark=[2]), kv=KV([['编排式', '编排器直接调用三个服务'], ['协同式', '服务之间用事件接力,3 条消息'], ['谁知道流程', '编排器 / 没有人']], ['谁知道流程'])),
    step("支付失败(余额只有 50)时的补偿。编排式:库存预留成功后调支付返回“余额不足”,编排器自己决定补偿——调库存服务 stock_release,再把订单改成 CANCELLED,整个过程 1.6 ms,编排器每一步都在日志里。协同式:支付服务发出 payment.failed,库存服务收到后自己释放并发出 stock.released,订单服务收到后取消,共 4 条消息;补偿的链条是由事件订阅关系隐含地串起来的。两边的终态都一样:订单 CANCELLED、库存回到 100、余额 50、没扣款。", t=tl(S(2)), mark=lidx(S(2), '失败:用户 1 余额不足', '发出 payment.failed'), done=lidx(S(2), '订单 → CANCELLED', '收到 stock.released'), kv=KV([['编排式', '编排器调用补偿(stock_release)'], ['协同式', 'payment.failed → stock.released → 订单取消'], ['终态', '库存 100,余额 50,订单 CANCELLED']], ['终态'])),
    step("库存不足(库存 0)是第一步就失败的情形,没有任何东西需要补偿。编排式:调库存服务失败(0.5 ms),编排器直接把订单改成 CANCELLED。协同式:库存服务发出 stock.failed(9.3 ms),订单服务收到后取消。两者终态一致:订单 CANCELLED、库存 0、余额 1000000、没有扣款。", t=tl(S(3)), mark=lidx(S(3), '失败:sku-1 库存不足', '发出 stock.failed'), done=lidx(S(3), '订单 → CANCELLED', '收到 stock.failed'), kv=KV([['第一步就失败', '没有要补偿的'], ['编排式', '编排器直接取消订单'], ['协同式', 'stock.failed → 订单取消']], ['第一步就失败'])),
    step("库存服务挂了 2 秒,两种写法的表现很不一样。编排式(每步最多重试 2 次、间隔 0.3 秒):编排器在 7.8 ms 第一次收到临时错误,312.7 ms、617.7 ms 又失败两次,重试用完后补偿并把订单取消,订单状态 0.05s PENDING → 0.63s CANCELLED。协同式(库存服务的消费者暂停 2 秒):消息安静地排在队列里,订单一直是 PENDING,直到库存服务回来、2.06s 时订单变成 CONFIRMED。编排器在第一次失败时就知道出事了、并按自己的策略处理;协同式里没有谁“知道”这单卡住了,但消息队列帮它扛过了故障。", t=tl(S(4)), mark=lidx(S(4), '重试用完,订单 → CANCELLED'), done=lidx(S(4), '协同式(库存服务的消费者暂停 2 秒'), b=bars([['编排式:订单被取消的时刻 s', 0.63, '0.63'], ['协同式:订单被确认的时刻 s', 2.06, '2.06']], 2.1, mark=[0], done=[1]), kv=KV([['编排式', '重试用完就补偿取消(0.63 s)'], ['协同式', '消息留在队列,服务回来后完成(2.06 s)'], ['代价', '协同式没有谁知道这单卡住了']], ['代价'])),
    step("想知道“订单 o-1 现在处在哪一步”:协同式要分别去三个服务的库里查,得到订单服务 CONFIRMED、库存服务 RESERVED、支付服务 CHARGED,要拼起来才知道整体状态。编排式如果让编排器把每个 saga 的当前步骤存在自己的表里,查一个地方就够——但本篇的编排器只在内存里记,没有持久化,这一点没有验证,持久化与观察放到第 30 篇。", t=tl(S(5)), mark=lidx(S(5), '协同式:要分别去 3 个服务'), done=lidx(S(5), '编排式:编排器如果'), kv=KV([['协同式', '查 3 个服务的库再拼起来'], ['编排式', '查编排器自己的 1 张表(设想)'], ['本篇没验证', '编排器持久化步骤']], ['协同式'])),
    step("各跑 150 笔成功订单(顺序执行)的端到端耗时。编排式是函数调用:中位数 0.5 ms、p99 1.0 ms。协同式要经过三次 RabbitMQ 的“发布 → broker → 消费”:中位数 1.4 ms、p99 3.0 ms。协同式每一跳都更慢,换来的是调用方不必在线、下游挂了消息还在(上一步已经看到)。", t=tl(S(6)), mark=lidx(S(6), '协同式(RabbitMQ)'), done=lidx(S(6), '编排式  '), b=bars([['编排式 中位数 ms', 0.5, '0.5'], ['协同式 中位数 ms', 1.4, '1.4'], ['编排式 p99 ms', 1.0, '1.0'], ['协同式 p99 ms', 3.0, '3.0']], 3.2, cur=[0, 2], mark=[1, 3]), kv=KV([['中位数', '0.5 ms → 1.4 ms'], ['p99', '1.0 ms → 3.0 ms'], ['换来的', '下游挂了消息还在']], ['换来的'])),
    step("在库存和支付之间加一个“积分”步骤,已有的东西要改几处。编排式:流程定义是一张步骤表,只加 1 行(+积分 points_grant points_release),库存、支付服务的代码不动。协同式:新增积分服务订阅 stock.reserved 和 payment.failed;已有的库存服务要把补偿触发源从 payment.failed 改成 points.released,已有的支付服务要把触发源从 stock.reserved 改成 points.granted——2 个已有服务必须改订阅,订单服务不变。四个服务的协同式跑支付失败,事件链 order.created → stock.reserved → points.granted → payment.failed → points.released → stock.released,订单 CANCELLED。", t=tl(S(7)), mark=lidx(S(7), '编排式:流程定义是一张步骤表', '协同式:新增 积分服务'), done=lidx(S(7), '四个服务的协同式'), b=bars([['编排式:需要改的已有组件', 0, '0(只改编排器的步骤表)'], ['协同式:需要改订阅的已有服务', 2, '2']], 2, done=[0], mark=[1]), kv=KV([['编排式', '步骤表加 1 行'], ['协同式', '2 个已有服务要改订阅'], ['原因', '服务之间通过事件名耦合']], ['原因'])),
]
A = mkartt('t8', 8, '分布式事务,Saga,编排式,协同式,RabbitMQ,MySQL,真实验证,动画演示',
    '用订单、库存、支付三个服务实测 Saga 的两种写法:编排式一个编排器调用三个服务(21.3 ms),协同式用 RabbitMQ 事件接力(3 条消息);支付失败时补偿路径不同、终态相同;库存服务挂 2 秒编排式 0.63 s 取消、协同式 2.06 s 完成;加一个积分步骤,编排式改 1 行,协同式要改 2 个已有服务的订阅。',
    'Saga 用一串本地事务加补偿来代替分布式事务。谁来决定下一步做什么?集中在一个编排器里,还是让服务自己看事件接力?这篇用三个服务和真实的 RabbitMQ,把两种写法的成功、失败、服务宕机、加一步的修改成本逐一跑出来。',
    [('21.3 ms vs 16.7 ms', '同一笔成功订单,编排式与协同式从开始到订单确认的时间(编排式没有消息,协同式 3 条消息)'), ('0.63 s vs 2.06 s', '库存服务挂 2 秒:编排式重试用完取消订单的时刻 vs 协同式服务恢复后完成的时刻'), ('1 行 vs 2 个服务', '加一个积分步骤:编排式改步骤表的行数 vs 协同式要改订阅的已有服务数')],
    [('成功的一单', '<p>编排式是一个编排器顺序调用服务;协同式是服务之间用 order.created、stock.reserved、payment.succeeded 事件接力。数据结果一样,区别是谁掌握整个流程。</p>'),
     ('支付失败的补偿', '<p>编排式由编排器主动调用 stock_release;协同式由 payment.failed 事件触发库存服务自己释放。补偿链条隐含在订阅关系里。</p>'),
     ('第一步就失败', '<p>库存不足时没有任何东西要补偿,两种写法都直接取消订单。</p>'),
     ('服务挂了', '<p>编排器知道失败,按重试与补偿策略决定;协同式靠消息队列缓冲,服务回来后自动完成,但没有谁知道这单卡住了。</p>'),
     ('查状态', '<p>协同式要拼三个服务的状态;编排式可以把当前步骤放在自己的表里(本篇没有持久化,留到第 30 篇)。</p>'),
     ('延迟', '<p>协同式每一跳多一次 broker 往返,中位数 0.5 ms 对 1.4 ms,换来调用方不必在线。</p>'),
     ('加一步的修改成本', '<p>编排式只改步骤表;协同式里已有服务通过事件名耦合,2 个已有服务要改订阅。</p>')],
    steps,
    [ENV_T + '。本篇三个服务的库是同一个 MySQL 26.7.0 实例里的三个 schema(服务之间没有跨库事务);协同式用真实的 RabbitMQ 4.3.6(topic 交换机、每个服务一个独占队列、pika 1.4.4);“服务挂了”是让订单状态轮询期间库存服务返回临时错误(编排式)或暂停消费者(协同式);编排器与服务是进程内的函数 / 线程,不是真正分布在多台机器上',
     '没有验证:编排器自己崩溃后怎么恢复(没有持久化步骤,第 9 篇和第 30 篇再做);协同式里事件丢失与重复(第 15 篇);Seata、Camunda、Temporal 等产品的实际表现;更多服务、分支更多的流程下两种写法的复杂度差别;“加一步需要改几处”只是对我自己这份实现的计数,不代表所有框架'],
    'Saga 的两种写法')
